// Project and changelog pages (generated by scripts/build-projects.mjs). Plain JS.
(() => {
  const root = document.documentElement;
  root.classList.add('js');
  const $ = (s, el = document) => el.querySelector(s);

  /* Theme, same switch as the homepage */
  const themeBtn = $('.theme-btn');
  if (themeBtn) themeBtn.addEventListener('click', () => {
    const current = root.dataset.theme || (matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
    const next = current === 'light' ? 'dark' : 'light';
    root.dataset.theme = next;
    try { localStorage.setItem('theme', next); } catch (e) { /* storage blocked: theme just won't persist */ }
  });

  const nav = $('.nav');
  if (nav) {
    const onScroll = () => nav.classList.toggle('is-stuck', scrollY > 8);
    addEventListener('scroll', onScroll, { passive: true });
    onScroll();
  }

  /* The pages are rebuilt once a day, so "3 days ago" is worked out here.
     The exact date stays in the tooltip. */
  const rel = new Intl.RelativeTimeFormat('en', { numeric: 'auto' });
  const today = Date.UTC(new Date().getFullYear(), new Date().getMonth(), new Date().getDate());
  document.querySelectorAll('time[data-rel]').forEach(t => {
    const days = Math.round((today - Date.parse(t.dateTime + 'T00:00:00Z')) / 864e5);
    if (!(days >= 0)) return;
    t.title = t.textContent;
    t.textContent = days < 30 ? rel.format(-days, 'day')
      : days < 365 ? rel.format(-Math.round(days / 30.4), 'month')
      : rel.format(-Math.round(days / 365), 'year');
  });

  /* Automation Test Platform: play the recorded walkthrough over the screenshot */
  const atp = $('[data-atp]');
  if (atp && window.AtpDemo && !matchMedia('(prefers-reduced-motion: reduce)').matches) AtpDemo(atp);

  /* Changelog: open the collapsed notes of an entry someone linked to */
  const target = location.hash && document.getElementById(location.hash.slice(1));
  const more = target && target.querySelector('.entry__more');
  if (more) more.open = true;
})();
